using Forjix.Api.Authorization;
using Forjix.Application.Common;
using Forjix.Application.Features.Cash;
using Microsoft.AspNetCore.Mvc;
namespace Forjix.Api.Controllers; [ApiController, Route("api/cash")] public sealed class CashController(ICashService service) : ControllerBase { [HttpGet("current"), RequirePermission(Permissions.CashView)] public async Task<ActionResult<CashSessionView?>> Current(CancellationToken ct) => Ok(await service.GetCurrentAsync(ct)); [HttpPost("open"), RequirePermission(Permissions.CashManage)] public async Task<ActionResult<CashSessionView>> Open(OpenCashRequest r, CancellationToken ct) => StatusCode(201, await service.OpenAsync(r, ct)); [HttpPost("supply"), RequirePermission(Permissions.CashManage)] public async Task<ActionResult<CashSessionView>> Supply(CashOperationRequest r, CancellationToken ct) => Ok(await service.SupplyAsync(r, ct)); [HttpPost("withdraw"), RequirePermission(Permissions.CashManage)] public async Task<ActionResult<CashSessionView>> Withdraw(CashOperationRequest r, CancellationToken ct) => Ok(await service.WithdrawAsync(r, ct)); [HttpPost("close"), RequirePermission(Permissions.CashManage)] public async Task<ActionResult<CashSessionView>> Close(CloseCashRequest r, CancellationToken ct) => Ok(await service.CloseAsync(r, ct)); }
